local CrownMaker = {}
local PRODUCTS = {
    bronze_circlet = { name = "Bronasta diadem", bronzeCost = 1, time = 2, cost = 30, prestige = 2, description = "Preprost bronast diadem za nižje plemstvo." },
    silver_coronet = { name = "Srebrna korona", silverCost = 2, time = 3, cost = 80, prestige = 5, happiness = 1, description = "Srebrna korona za viteze in barone." },
    gold_circlet = { name = "Zlat diadem", goldCost = 1, time = 4, cost = 180, prestige = 10, happiness = 1, description = "Zlat diadem za grofe in vojvode." },
    jeweled_coronet = { name = "Draguljna korona", goldCost = 1, silverCost = 1, jewelCost = 1, time = 5, cost = 350, prestige = 15, happiness = 2, description = "Z dragulji okrašena korona." },
    royal_open_crown = { name = "Kraljevska odprta krona", goldCost = 2, silverCost = 2, jewelCost = 2, time = 7, cost = 700, prestige = 22, happiness = 4, description = "Odprta krona z loki in dragulji za kralje." },
    imperial_crown = { name = "Cesarska zaprta krona", goldCost = 4, silverCost = 3, jewelCost = 4, pearlCost = 2, time = 10, cost = 1500, prestige = 50, happiness = 10, description = "Zaprt tip cesarske krone z največjimi dragulji cesarstva." },
}
local BUILDINGS = {
    workshop = { name = "Kronarska delavnica", cost = { gold = 300, wood = 100 }, upkeep = 8, qualityBonus = 5 },
    forge = { name = "Kronarska kovačija", cost = { gold = 900, wood = 200, stone = 200, gold = 10 }, upkeep = 22, qualityBonus = 18 },
    jewel_room = { name = "Draguljarska soba", cost = { gold = 2000, wood = 300, stone = 400, silver = 50, jewel = 10 }, upkeep = 50, qualityBonus = 30 },
    royal_crown_atelier = { name = "Kraljevski atelje kron", cost = { gold = 8000, wood = 600, stone = 800, gold = 100, jewel = 30 }, upkeep = 150, qualityBonus = 55, prestigeBonus = 35 },
}
CrownMaker.bronzeStock = 12; CrownMaker.silverStock = 8; CrownMaker.goldStock = 6; CrownMaker.jewelStock = 6; CrownMaker.pearlStock = 4
CrownMaker.productStock = {}; CrownMaker.buildings = {}; CrownMaker.maker = nil; CrownMaker.activeMaking = {}; CrownMaker.totalProducts = 0; CrownMaker.dayTimer = 0
function CrownMaker.init() CrownMaker.bronzeStock=12; CrownMaker.silverStock=8; CrownMaker.goldStock=6; CrownMaker.jewelStock=6; CrownMaker.pearlStock=4; CrownMaker.productStock={}; CrownMaker.buildings={}; CrownMaker.maker=nil; CrownMaker.activeMaking={}; CrownMaker.totalProducts=0; CrownMaker.dayTimer=0; print("[CrownMaker] Royal Crown Maker System initialized (6 products, 4 buildings)") end
function CrownMaker.hireMaker(n,s) s=s or math.random(50,90); local c=500+s*10; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CrownMaker.maker={name=n or ("Kronar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Kronar najet: %s (spretnost: %d)",CrownMaker.maker.name,s),"success") end; return true end
function CrownMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CrownMaker.build(id) local ok,e=CrownMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CrownMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CrownMaker.getQualityBonus() local b=0; for _,bd in ipairs(CrownMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CrownMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.bronzeCost and CrownMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.silverCost and CrownMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CrownMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CrownMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CrownMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CrownMaker.buildings==0 then return false,"Potrebna delavnica" end; if not CrownMaker.maker then return false,"Potreben kronar" end; return true end
function CrownMaker.make(pt,qty) qty=qty or 1; local ok,e=CrownMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.bronzeCost then CrownMaker.bronzeStock=CrownMaker.bronzeStock-d.bronzeCost*qty end; if d.silverCost then CrownMaker.silverStock=CrownMaker.silverStock-d.silverCost*qty end; if d.goldCost then CrownMaker.goldStock=CrownMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CrownMaker.jewelStock=CrownMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CrownMaker.pearlStock=CrownMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CrownMaker.maker then t=math.max(1,t-math.floor(CrownMaker.maker.skill/12)) end; table.insert(CrownMaker.activeMaking,{id="crown_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CrownMaker.completeMaking(m) local q=1.0+(CrownMaker.getQualityBonus()/100); if CrownMaker.maker then q=q+(CrownMaker.maker.skill/180) end; q=math.min(2.0,q); CrownMaker.productStock[m.productType]=(CrownMaker.productStock[m.productType] or 0)+m.quantity; CrownMaker.totalProducts=CrownMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CrownMaker.maker then CrownMaker.maker.itemsMade=CrownMaker.maker.itemsMade+m.quantity; if math.random()<0.20 then CrownMaker.maker.skill=math.min(100,CrownMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Krona izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"crown.completed",{productName=m.productName,prestige=m.prestige}) end end
function CrownMaker.update(dt) if not _G.state then return end; CrownMaker.dayTimer=CrownMaker.dayTimer+dt; if CrownMaker.dayTimer>=30 then CrownMaker.dayTimer=0; for i=#CrownMaker.activeMaking,1,-1 do local m=CrownMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CrownMaker.completeMaking(m); table.remove(CrownMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CrownMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CrownMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CrownMaker.getStats() return {bronzeStock=CrownMaker.bronzeStock,silverStock=CrownMaker.silverStock,goldStock=CrownMaker.goldStock,jewelStock=CrownMaker.jewelStock,pearlStock=CrownMaker.pearlStock,productStock=CrownMaker.productStock,numBuildings=#CrownMaker.buildings,hasMaker=CrownMaker.maker~=nil,makerName=CrownMaker.maker and CrownMaker.maker.name or "—",makerSkill=CrownMaker.maker and CrownMaker.maker.skill or 0,activeMaking=#CrownMaker.activeMaking,totalProducts=CrownMaker.totalProducts} end
return CrownMaker
